1	//! Plugin loader - discovers state plugins and instantiates them
2	//!
3	//! This module deliberately does not maintain a second plugin list. If a state
4	//! plugin exists in `state_plugins`, the registry discovers it and registers it.
5	//!
6	//! ## Schema Validation
7	//!
8	//! Plugins are validated against JSON schema files at runtime.
9	//! If a schema file is missing in strict mode, the plugin will be rejected.
10	//! Schema files are loaded from `schemas/plugin/{name}.json`.
11	//!
12	//! ## Canonical Path Enforcement
13	//!
14	//! All plugins must use canonical D-Bus paths:
15	//! - Path: `/org/opdbus/v1/plugins/{name}`
16	//! - Interface: `org.opdbus.v1.Plugin.Plugins.{Name}`
17	//!
18	//! Legacy paths are deprecated and will be rejected.
19	
20	use anyhow::{anyhow, Result};
21	use op_state_store::StateStore;
22	use simd_json::prelude::*;
23	use std::sync::Arc;
24	
25	use crate::schema_loader::SchemaLoader;
26	
27	use crate::AutoPlugin;
28	
29	/// Context handed to a plugin's registered constructor at load time. Wraps the
30	/// registry so co-located registrations can reach the few inputs a constructor
31	/// needs (state store, config-path resolution) without exposing private fields.
32	pub struct PluginCtx<'a> {
33	    reg: &'a DefaultPluginRegistry,
34	}
35	
36	impl PluginCtx<'_> {
37	    /// Shared state store (used by e.g. the `mcp` plugin).
38	    pub fn state_store(&self) -> Arc<dyn StateStore> {
39	        self.reg.state_store.clone()
40	    }
41	
42	    /// Resolve a plugin's configured `config_path`, falling back to `default`.
43	    pub fn config_path(&self, plugin_name: &str, default: &str) -> String {
44	        self.reg.get_plugin_config_path(plugin_name, default)
45	    }
46	}
47	
48	/// A single plugin's self-registration: its canonical name plus a constructor.
49	///
50	/// Each plugin module emits one of these via [`inventory::submit!`], co-located
51	/// with the plugin's own definition. The registry iterates the collected set —
52	/// this is the **only** plugin catalog; there is no central dispatch list.
53	pub struct PluginReg {
54	    /// Canonical loader name (what `load_plugin` / `available_plugins` expose).
55	    pub name: &'static str,
56	    /// Constructor. `build` (not `ctor`/`actor`) to avoid any confusion with the
57	    /// MutationEngine `actor_id` identity concept.
58	    pub build: fn(&PluginCtx) -> Arc<dyn op_state::StatePlugin>,
59	}
60	
61	impl PluginReg {
62	    pub const fn new(
63	        name: &'static str,
64	        build: fn(&PluginCtx) -> Arc<dyn op_state::StatePlugin>,
65	    ) -> Self {
66	        Self { name, build }
67	    }
68	}
69	
70	inventory::collect!(PluginReg);
71	
72	/// Default plugin loader configuration
73	#[derive(Debug, Clone, serde::Serialize, serde::Deserialize)]
74	pub struct PluginRegistryConfig {
75	    /// Deprecated runtime policy field. Registration is discovery-based.
76	    #[serde(default = "default_auto_load")]
77	    pub auto_load: Vec<String>,
78	
79	    /// Plugin-specific configurations
80	    #[serde(default)]
81	    pub plugin_configs: std::collections::HashMap<String, simd_json::OwnedValue>,
82	}
83	
84	fn default_auto_load() -> Vec<String> {
85	    Vec::new()
86	}
87	
88	impl Default for PluginRegistryConfig {
89	    fn default() -> Self {
90	        Self {
91	            auto_load: default_auto_load(),
92	            plugin_configs: std::collections::HashMap::new(),
93	        }
94	    }
95	}
96	
97	/// Default plugin loader.
98	///
99	/// This is intentionally not the authoritative plugin catalog. Its job is to
100	/// instantiate the built-in plugin implementations so the real catalog path can
101	/// persist their canonical plugin documents during registration.
102	pub struct DefaultPluginRegistry {
103	    config: PluginRegistryConfig,
104	    state_store: Arc<dyn StateStore>,
105	    schema_loader: SchemaLoader,
106	}
107	
108	impl DefaultPluginRegistry {
109	    /// Create a new plugin loader
110	    pub fn new(state_store: Arc<dyn StateStore>) -> Self {
111	        Self {
112	            config: PluginRegistryConfig::default(),
113	            state_store,
114	            schema_loader: SchemaLoader::new("schemas/plugin"),
115	        }
116	    }
117	
118	    /// Create with custom schema directory
119	    pub fn with_schema_dir(
120	        state_store: Arc<dyn StateStore>,
121	        schema_dir: impl Into<std::path::PathBuf>,
122	    ) -> Self {
123	        Self {
124	            config: PluginRegistryConfig::default(),
125	            state_store,
126	            schema_loader: SchemaLoader::new(schema_dir),
127	        }
128	    }
129	
130	    /// Validate a plugin has a valid schema file
131	    ///
132	    /// Returns Ok(()) if schema exists and is valid
133	    /// Returns Err if schema is missing or invalid (in strict mode)
134	    pub async fn validate_plugin_schema(&self, plugin_name: &str) -> Result<()> {
135	        match self.schema_loader.load_schema(plugin_name).await? {
136	            Some(_) => Ok(()),
137	            None => Err(anyhow!(
138	                "Plugin '{}' has no valid schema file. Expected: schemas/plugin/{}.json",
139	                plugin_name,
140	                plugin_name
141	            )),
142	        }
143	    }
144	
145	    /// Check if a schema file exists for a plugin
146	    pub async fn schema_exists(&self, plugin_name: &str) -> bool {
147	        self.schema_loader.schema_exists(plugin_name).await
148	    }
149	
150	    /// Create with custom configuration
151	    pub fn with_config(state_store: Arc<dyn StateStore>, config: PluginRegistryConfig) -> Self {
152	        Self {
153	            config,
154	            state_store,
155	            schema_loader: SchemaLoader::new("schemas/plugin"),
156	        }
157	    }
158	
159	    /// Create with custom configuration and schema directory
160	    pub fn with_config_and_schema_dir(
161	        state_store: Arc<dyn StateStore>,
162	        config: PluginRegistryConfig,
163	        schema_dir: impl Into<std::path::PathBuf>,
164	    ) -> Self {
165	        Self {
166	            config,
167	            state_store,
168	            schema_loader: SchemaLoader::new(schema_dir),
169	        }
170	    }
171	
172	    /// Resolve user/request-facing plugin references into canonical loader names.
173	    ///
174	    /// Supports direct names, aliases, and projection paths like
175	    /// `/org/opdbus/v1/plugins/<plugin>/...`.
176	    ///
177	    /// The old `/org/opdbus/v1/plugin/plugins/...` spelling is accepted as a
178	    /// compatibility alias and normalized to the canonical plural base path.
179	    pub fn resolve_requested_plugin_name(requested: &str) -> Result<String> {
180	        let trimmed = requested.trim();
181	        if trimmed.is_empty() {
182	            return Err(anyhow!("Plugin identifier cannot be empty"));
183	        }
184	
185	        let extracted = Self::extract_plugin_name_from_projection_path(trimmed);
186	        let from_path = extracted.as_deref().unwrap_or(trimmed);
187	        let normalized = from_path
188	            .trim()
189	            .trim_matches('/')
190	            .replace('-', "_")
191	            .to_lowercase();
192	
193	        let canonical = match normalized.as_str() {
194	            "network" => "net",
195	            "systemd" | "dinit" | "service_s6" => "s6",
196	            "web_ui" | "webui" => "web_ui",
197	            "mail" | "mailserver" => "mail_server",
198	            "ovsbridge" => "ovsdb_bridge",
199	            "rtnet" => "rtnetlink",
200	            "sessdecl" => "sess_decl",
201	            other => other,
202	        };
203	
204	        Ok(canonical.to_string())
205	    }
206	
207	    fn extract_plugin_name_from_projection_path(requested: &str) -> Option<String> {
208	        // Normalize aliases first, then extract the top-level plugin name.
209	        let normalized = crate::canonical::normalize_plugin_path(requested)?;
210	        normalized
211	            .strip_prefix(crate::canonical::PLUGIN_BASE_PATH)?
212	            .trim_start_matches('/')
213	            .split('/')
214	            .find(|segment| !segment.is_empty())
215	            .map(|segment| segment.to_string())
216	    }
217	
218	    /// Compatibility shim for older callers. Registration is discovery-based:
219	    /// if a state plugin exists, it is loaded.
220	    pub async fn load_default_plugins(&self) -> Result<Vec<Arc<dyn op_state::StatePlugin>>> {
221	        self.load_all_plugins().await
222	    }
223	
224	    /// Load every built-in plugin implementation so the schema catalog can
225	    /// publish the full plugin contract set, not just runtime autoload state.
226	    pub async fn load_all_plugins(&self) -> Result<Vec<Arc<dyn op_state::StatePlugin>>> {
227	        let mut plugins: Vec<Arc<dyn op_state::StatePlugin>> = Vec::new();
228	        let mut plugin_names = Self::available_plugins();
229	
230	        plugin_names.sort();
231	        plugin_names.dedup();
232	
233	        for plugin_name in plugin_names {
234	            match self.load_plugin(&plugin_name).await {
235	                Ok(plugin) => {
236	                    if !plugin.is_available() {
237	                        tracing::info!(
238	                            "Loaded unavailable plugin schema {}: {}",
239	                            plugin_name,
240	                            plugin.unavailable_reason()
241	                        );
242	                    } else {
243	                        tracing::info!("Loaded plugin schema: {}", plugin_name);
244	                    }
245	                    plugins.push(plugin);
246	                }
247	                Err(e) => {
248	                    tracing::warn!("Failed to load plugin schema {}: {}", plugin_name, e);
249	                }
250	            }
251	        }
252	
253	        tracing::info!("Loaded {} built-in plugin schemas", plugins.len());
254	        Ok(plugins)
255	    }
256	
257	    /// Load a specific plugin by name.
258	    ///
259	    /// Resolves the request to a canonical name, then looks it up in the
260	    /// inventory of plugin self-registrations (each plugin module emits a
261	    /// [`PluginReg`] via `inventory::submit!`). Unknown names fall through to the
262	    /// auto-create review-required draft. There is no central dispatch list.
263	    pub async fn load_plugin(&self, name: &str) -> Result<Arc<dyn op_state::StatePlugin>> {
264	        let resolved_name = Self::resolve_requested_plugin_name(name)?;
265	
266	        let ctx = PluginCtx { reg: self };
267	        for registration in inventory::iter::<PluginReg> {
268	            if registration.name == resolved_name {
269	                return Ok((registration.build)(&ctx));
270	            }
271	        }
272	
273	        let requested_info = format!("requested='{}' resolved='{}'", name, resolved_name);
274	        tracing::warn!(
275	            "Unknown plugin '{}'; auto-creating review-required draft from requested info",
276	            name
277	        );
278	        Ok(Arc::new(
279	            AutoPlugin::create_from_requested_info(&resolved_name, &requested_info).await,
280	        ))
281	    }
282	
283	    /// Get plugin-specific config value or default
284	    fn get_plugin_config_path(&self, plugin_name: &str, default: &str) -> String {
285	        self.config
286	            .plugin_configs
287	            .get(plugin_name)
288	            .and_then(|v| v.get("config_path"))
289	            .and_then(|v| v.as_str())
290	            .unwrap_or(default)
291	            .to_string()
292	    }
293	
294	    /// The plugin catalog: every name self-registered via `inventory::submit!`.
295	    ///
296	    /// This is intentionally not a hand-maintained list. Each plugin module is
297	    /// the single source of its own registration; this just collects them.
298	    /// Unknown subjects still flow through `load_plugin()` and the auto-create
299	    /// fallback.
300	    pub fn available_plugins() -> Vec<String> {
301	        let mut plugins: Vec<String> = inventory::iter::<PluginReg>
302	            .into_iter()
303	            .map(|registration| registration.name.to_string())
304	            .collect();
305	
306	        plugins.sort();
307	        plugins.dedup();
308	        plugins
309	    }
310	
311	    /// Get list of plugins with valid schema files
312	    pub async fn available_schemas(&self) -> Result<Vec<String>> {
313	        self.schema_loader.list_available_schemas().await
314	    }
315	
316	    /// Load schema for a plugin
317	    pub async fn load_plugin_schema(
318	        &self,
319	        plugin_name: &str,
320	    ) -> Result<Option<op_state::PluginSchema>> {
321	        self.schema_loader.load_schema(plugin_name).await
322	    }
323	
324	    /// Check if a plugin is enabled for auto-load
325	    pub fn is_auto_load(&self, plugin_name: &str) -> bool {
326	        self.config.auto_load.contains(&plugin_name.to_string())
327	    }
328	}
