506	    #[tokio::test]
507	    async fn all_plugin_subids_are_valid_and_unique() {
508	        use crate::state_plugins::common::oscal::{category_required_fields, validate_subid};
509	        use std::collections::HashMap;
510	
511	        let store = Arc::new(MemoryStore::new());
512	        let registry = DefaultPluginRegistry::new(store);
513	        let plugins = registry.load_all_plugins().await.unwrap();
514	
515	        let mut all_subids: Vec<(String, String, String)> = Vec::new(); // plugin, key, subid
516	        let mut errors: Vec<String> = Vec::new();
517	
518	        for plugin in &plugins {
519	            let name = plugin.name().to_string();
520	            let Some(schema) = plugin.schema() else {
521	                continue;
522	            };
523	            for (key, subid) in &schema.subids {
524	                all_subids.push((name.clone(), key.clone(), subid.clone()));
525	            }
526	        }
527	
528	        // 1. Every subid must match the canonical OSCAL subid regex.
529	        for (plugin_name, key, subid) in &all_subids {
530	            if let Err(e) = validate_subid(subid) {
531	                errors.push(format!(
532	                    "plugin '{plugin_name}' key '{key}' has invalid subid '{subid}': {e}"
533	                ));
534	            }
535	        }
536	
537	        // 2. No subid value may appear more than once across all plugins.
538	        let mut seen: HashMap<String, (String, String)> = HashMap::new();
539	        for (plugin_name, key, subid) in &all_subids {
540	            if let Some((prev_plugin, prev_key)) = seen.get(subid) {
541	                errors.push(format!(
542	                    "duplicate subid '{subid}' in plugin '{plugin_name}' key '{key}' (first seen in plugin '{prev_plugin}' key '{prev_key}')"
543	                ));
544	            } else {
545	                seen.insert(subid.clone(), (plugin_name.clone(), key.clone()));
546	            }
547	        }
548	
549	        // 3. Category-specific required metadata fields must be present in the plugin schema.
550	        for (plugin_name, key, subid) in &all_subids {
551	            let Some(schema) = plugins
552	                .iter()
553	                .find(|p| p.name() == plugin_name)
554	                .and_then(|p| p.schema())
555	            else {
556	                continue;
557	            };
558	            let category = subid.split('.').next().unwrap_or("");
559	            let required_fields = category_required_fields(category);
560	            if category == "evt" {
561	                // evt.* requires at least one of event_id or event_hash.
562	                if !required_fields
563	                    .iter()
564	                    .any(|field| schema.fields.contains_key(*field))
565	                {
566	                    errors.push(format!(
567	                        "plugin '{plugin_name}' subid '{subid}' (key '{key}') is evt.* and requires one of {:?} fields, but none found in schema fields",
568	                        required_fields
569	                    ));
570	                }
571	            } else if !required_fields.is_empty() {
572	                for field in required_fields {
573	                    if !schema.fields.contains_key(*field) {
574	                        errors.push(format!(
575	                            "plugin '{plugin_name}' subid '{subid}' (key '{key}') is {category}.* and requires field '{field}', but it is not present in schema fields"
576	                        ));
577	                    }
578	                }
579	            }
580	        }
581	
582	        assert!(
583	            errors.is_empty(),
584	            "OSCAL subid gate failures:\n{}",
585	            errors.join("\n")
586	        );
587	    }
588	}
