//! Gemma brain — the umbrella cognitive plugin.
//!
//! Gemma does multiple things, so this is a "brain", not a "router": it owns the
//! tag-routing / subid-classification configuration, the four reasoning
//! perspectives, the UI-spec gallery surface, and the operator chat surface. It
//! is the WHAT-to-decide surface; it **consumes** the generic
//! [`super::large_language_model`] plugin for inference and embeds no model of
//! its own ("gemma" here is a brand for the brain, not a model binding — swap
//! the underlying model via the `large_language_model` plugin).
//!
//! Bulk gallery generation lives in the `op-gemma` binary → Ollama. This
//! plugin reports the live observed state (gallery population, op-gemma
//! availability) and the operator-set routing configuration. Mutations
//! (chat / generate / promote / delete) are routed by the MutationEngine via
//! [`dispatch_gemma_brain_method`], not performed in this plugin's
//! `apply_state` (which, like every StatePlugin, is declarative).
//!
//! Chat-built elements land in the gallery (`/dev/shm/gemma-ui-specs.json`);
//! `promote_spec` copies an element into the promoted site catalog
//! (`/dev/shm/opdbus/gemma-ui-catalog.json`) that the json-render UI consumes.
//! Durability is the mutation chain — every chat/promote/delete is a recorded
//! mutation; the SHM artifacts are present-state projections.

use anyhow::Result;
use async_trait::async_trait;
use op_state::{ApplyResult, Checkpoint, DiffMetadata, PluginCapabilities, StateDiff, StatePlugin};
use op_state_store::PluginSchema;
use serde::{Deserialize, Serialize};
use simd_json::OwnedValue as Value;

/// Path to the UI-spec gallery produced by the `op-gemma` binary and chat.
const GEMMA_SPECS_PATH: &str = "/dev/shm/gemma-ui-specs.json";
/// Promoted site catalog: gallery entries the operator promoted for the site.
const GEMMA_CATALOG_PATH: &str = "/dev/shm/opdbus/gemma-ui-catalog.json";
/// Present-state chat transcript (durability is the mutation chain).
const GEMMA_CHAT_HISTORY_PATH: &str = "/dev/shm/opdbus/gemma-chat-history.json";
/// Max prior messages replayed to the model per turn.
const CHAT_CONTEXT_MESSAGES: usize = 24;

const CHAT_SYSTEM_PROMPT: &str = "You are Gemma, the 3tched/OP-DBUS build assistant, reached over the \
D-Bus control plane. When the operator gives a build instruction for a user-interface element, include \
exactly one fenced ```json code block containing a single json-render spec object that fulfils the \
stated intent, then briefly note your reasoning across the four perspectives (data/numeric, \
spatial/layout, user flow, context/aesthetic). For anything else, answer concisely.";

const GENERATE_SYSTEM_PROMPT: &str = "You produce json-render UI spec objects. Respond with ONLY one \
fenced ```json code block containing a single JSON object fulfilling the stated intent. No prose.";

/// Tag-routing / subid-classification configuration owned by the brain.
#[derive(Debug, Clone, Default, Serialize, Deserialize, schemars::JsonSchema)]
#[schemars(extend("x-oscal-subid" = "sch.software.gemma-brain.routing.schema@v1"))]
pub struct GemmaRouting {
    /// Whether Gemma performs OSCAL subid classification.
    #[serde(default)]
    #[schemars(extend("x-oscal-subid" = "mut.service.gemma-brain.subid-classification@v1"))]
    pub subid_classification: bool,
    /// Whether Gemma performs xray/OpenFlow tag routing.
    #[serde(default)]
    #[schemars(extend("x-oscal-subid" = "mut.service.gemma-brain.tag-routing@v1"))]
    pub tag_routing: bool,
    /// xray config the routing decisions are written into.
    #[serde(default)]
    #[schemars(extend("x-oscal-subid" = "src.service.gemma-brain.xray-config@v1"))]
    pub xray_config_path: String,
}

/// UI-spec gallery surface (the artifact the lovable SPA renders).
#[derive(Debug, Clone, Default, Serialize, Deserialize, schemars::JsonSchema)]
#[schemars(extend("x-oscal-subid" = "sch.software.gemma-brain.gallery.schema@v1"))]
pub struct GemmaGallery {
    /// Tmpfs path of the gallery JSON produced by `op-gemma`.
    #[serde(default)]
    #[schemars(extend("x-oscal-subid" = "exp.service.gemma-brain.gallery-path@v1"))]
    pub specs_path: String,
    /// Target number of specs the gallery is topped up to.
    #[serde(default)]
    #[schemars(extend("x-oscal-subid" = "mut.service.gemma-brain.target-count@v1"))]
    pub target_count: u32,
    /// Current number of specs present (observed live).
    #[serde(default)]
    #[schemars(extend("x-oscal-subid" = "obs.software.gemma-brain.spec-count@v1"))]
    pub spec_count: u32,
    /// Tmpfs path of the promoted site catalog.
    #[serde(default)]
    #[schemars(extend("x-oscal-subid" = "exp.service.gemma-brain.catalog-path@v1"))]
    pub catalog_path: String,
    /// Current number of promoted specs in the site catalog (observed live).
    #[serde(default)]
    #[schemars(extend("x-oscal-subid" = "obs.software.gemma-brain.catalog-count@v1"))]
    pub catalog_count: u32,
}

/// Top-level state for the Gemma brain.
#[derive(Debug, Clone, Default, Serialize, Deserialize, schemars::JsonSchema)]
#[schemars(extend("x-oscal-subid" = "sch.software.plugin.gemma-brain.schema@v1"))]
pub struct GemmaBrainState {
    /// Derived operational status (observed): `unavailable` (op-gemma binary
    /// missing), `empty`, `partial`, or `ready`.
    #[serde(default)]
    #[schemars(extend("x-oscal-subid" = "obs.software.gemma-brain.status@v1"))]
    pub status: String,
    /// The generic LLM plugin this brain consumes for inference. Not a model —
    /// the model is selected inside that plugin.
    #[serde(default)]
    #[schemars(extend("x-oscal-subid" = "mut.service.gemma-brain.llm-plugin@v1"))]
    pub llm_plugin: String,
    /// Enabled reasoning perspectives (the four axes).
    #[serde(default)]
    #[schemars(extend("x-oscal-subid" = "mut.service.gemma-brain.perspectives@v1"))]
    pub perspectives: Vec<String>,
    /// Routing / subid-classification configuration.
    #[serde(default)]
    #[schemars(extend("x-oscal-subid" = "mut.service.gemma-brain.routing@v1"))]
    pub routing: GemmaRouting,
    /// UI-spec gallery surface.
    #[serde(default)]
    #[schemars(extend("x-oscal-subid" = "sch.software.gemma-brain.gallery@v1"))]
    pub gallery: GemmaGallery,
}

pub struct GemmaBrainPlugin;

impl Default for GemmaBrainPlugin {
    fn default() -> Self {
        Self
    }
}

impl GemmaBrainPlugin {
    pub fn new() -> Self {
        Self
    }

    fn env_or(key: &str, fallback: &str) -> String {
        std::env::var(key).unwrap_or_else(|_| fallback.to_string())
    }

    fn env_bool(key: &str, fallback: bool) -> bool {
        std::env::var(key)
            .ok()
            .and_then(|v| match v.trim().to_ascii_lowercase().as_str() {
                "1" | "true" | "yes" | "on" => Some(true),
                "0" | "false" | "no" | "off" => Some(false),
                _ => None,
            })
            .unwrap_or(fallback)
    }

    fn env_u32(key: &str, fallback: u32) -> u32 {
        std::env::var(key)
            .ok()
            .and_then(|v| v.parse().ok())
            .unwrap_or(fallback)
    }

    /// Path of the `op-gemma` generator binary.
    fn gemma_binary() -> String {
        Self::env_or("GEMMA_BINARY_PATH", "/usr/local/bin/op-gemma")
    }

    /// Count the specs currently in a gallery-shaped artifact (0 if absent).
    fn spec_count_at(path: &str) -> u32 {
        std::fs::read(path)
            .ok()
            .and_then(|bytes| serde_json::from_slice::<serde_json::Value>(&bytes).ok())
            .and_then(|v| {
                v.get("specs")
                    .and_then(serde_json::Value::as_array)
                    .map(|a| a.len() as u32)
            })
            .unwrap_or(0)
    }

    /// Build the live state: observed fields are read from the system, config
    /// fields from the environment (with sensible defaults).
    fn current_state() -> GemmaBrainState {
        let target_count = Self::env_u32("GEMMA_TARGET_COUNT", 200);
        let spec_count = Self::spec_count_at(GEMMA_SPECS_PATH);
        let binary_present = std::path::Path::new(&Self::gemma_binary()).exists();

        let status = if !binary_present {
            "unavailable"
        } else if spec_count == 0 {
            "empty"
        } else if spec_count >= target_count {
            "ready"
        } else {
            "partial"
        }
        .to_string();

        GemmaBrainState {
            status,
            llm_plugin: Self::env_or("GEMMA_LLM_PLUGIN", "large_language_model"),
            perspectives: vec![
                "data_numeric".to_string(),
                "spatial_layout".to_string(),
                "user_flow".to_string(),
                "context_aesthetic".to_string(),
            ],
            routing: GemmaRouting {
                subid_classification: Self::env_bool("GEMMA_SUBID_CLASSIFICATION", true),
                tag_routing: Self::env_bool("GEMMA_TAG_ROUTING", true),
                xray_config_path: Self::env_or("GEMMA_XRAY_CONFIG", "/etc/xray/config.json"),
            },
            gallery: GemmaGallery {
                specs_path: GEMMA_SPECS_PATH.to_string(),
                target_count,
                spec_count,
                catalog_path: GEMMA_CATALOG_PATH.to_string(),
                catalog_count: Self::spec_count_at(GEMMA_CATALOG_PATH),
            },
        }
    }
}

#[async_trait]
impl StatePlugin for GemmaBrainPlugin {
    fn name(&self) -> &str {
        "gemma_brain"
    }

    fn version(&self) -> &str {
        "1.0.0"
    }

    /// Available only when the `op-gemma` generator binary is installed.
    fn is_available(&self) -> bool {
        std::path::Path::new(&Self::gemma_binary()).exists()
    }

    fn unavailable_reason(&self) -> String {
        format!(
            "op-gemma generator binary not found at {}",
            Self::gemma_binary()
        )
    }

    fn schema(&self) -> Option<PluginSchema> {
        let mut schema = gemma_brain_schema();
        super::common::oscal::ensure_category_metadata_fields(&mut schema);
        Some(schema)
    }

    async fn calculate_diff(&self, _current: &Value, _desired: &Value) -> Result<StateDiff> {
        Ok(StateDiff {
            plugin: self.name().to_string(),
            actions: vec![],
            metadata: DiffMetadata {
                timestamp: chrono::Utc::now().timestamp(),
                current_hash: "schema-declared".to_string(),
                desired_hash: "schema-declared".to_string(),
            },
        })
    }

    async fn apply_state(&self, _diff: &StateDiff) -> Result<ApplyResult> {
        Ok(ApplyResult {
            success: true,
            changes_applied: vec![],
            errors: vec![],
            checkpoint: None,
        })
    }

    async fn verify_state(&self, _desired: &Value) -> Result<bool> {
        Ok(true)
    }

    async fn create_checkpoint(&self) -> Result<Checkpoint> {
        Ok(Checkpoint {
            id: uuid::Uuid::new_v4().to_string(),
            plugin: self.name().to_string(),
            timestamp: chrono::Utc::now().timestamp(),
            state_snapshot: simd_json::serde::to_owned_value(Self::current_state())?,
            backend_checkpoint: None,
        })
    }

    async fn rollback(&self, _checkpoint: &Checkpoint) -> Result<()> {
        Ok(())
    }

    fn capabilities(&self) -> PluginCapabilities {
        PluginCapabilities {
            supports_rollback: false,
            supports_checkpoints: true,
            supports_verification: true,
            atomic_operations: false,
        }
    }
}

/// Canonical `gemma_brain` schema derived from [`GemmaBrainState`] via schemars.
pub(crate) fn gemma_brain_schema() -> PluginSchema {
    let root = serde_json::to_value(schemars::schema_for!(GemmaBrainState))
        .expect("schemars schema serializes to JSON");
    let mut schema = super::schemars_adapter::plugin_schema_from_json(
        "gemma_brain",
        "1.0.0",
        "Gemma cognitive brain: tag routing, subid classification, reasoning perspectives, operator chat, and UI-spec gallery with promote-to-catalog; consumes the large_language_model plugin for inference",
        &root,
    );

    // Output structs
    #[derive(Debug, Clone, Serialize, Deserialize, schemars::JsonSchema)]
    pub struct ClassifyOutput {
        pub classification: serde_json::Value,
    }
    #[derive(Debug, Clone, Serialize, Deserialize, schemars::JsonSchema)]
    pub struct RouteOutput {
        pub route: serde_json::Value,
    }
    #[derive(Debug, Clone, Serialize, Deserialize, schemars::JsonSchema)]
    pub struct ListPerspectivesOutput {
        pub perspectives: Vec<serde_json::Value>,
    }
    #[derive(Debug, Clone, Serialize, Deserialize, schemars::JsonSchema)]
    pub struct GetUiSpecOutput {
        pub spec: Option<serde_json::Value>,
    }
    #[derive(Debug, Clone, Serialize, Deserialize, schemars::JsonSchema)]
    pub struct ListTagsOutput {
        pub tags: Vec<serde_json::Value>,
    }
    #[derive(Debug, Clone, Serialize, Deserialize, schemars::JsonSchema)]
    pub struct AnalyzeIntentOutput {
        pub intent: serde_json::Value,
    }

    // Chat / gallery / catalog method IO
    #[derive(Debug, Clone, Serialize, Deserialize, schemars::JsonSchema)]
    pub struct ChatInput {
        /// Operator message / build instruction for Gemma.
        pub message: String,
        /// Start a fresh conversation (drop replayed context).
        #[serde(default)]
        pub reset: bool,
    }
    #[derive(Debug, Clone, Serialize, Deserialize, schemars::JsonSchema)]
    pub struct ChatOutput {
        pub reply: String,
        /// Model that answered (resolved by the large_language_model plugin).
        pub model: String,
        /// Gallery id of the element built this turn, if the reply contained one.
        pub spec_id: Option<String>,
        pub gallery_count: u32,
    }
    #[derive(Debug, Clone, Serialize, Deserialize, schemars::JsonSchema)]
    pub struct GenerateElementInput {
        /// Intent/function of the element (describe what it must do, not what it is).
        pub intent: String,
    }
    #[derive(Debug, Clone, Serialize, Deserialize, schemars::JsonSchema)]
    pub struct GenerateElementOutput {
        pub id: String,
        pub spec: serde_json::Value,
        pub gallery_count: u32,
    }
    #[derive(Debug, Clone, Serialize, Deserialize, schemars::JssonSchemaPlaceholder)]
    pub struct __Never; // removed before compile — see note in HANDOFF
    #[derive(Debug, Clone, Serialize, Deserialize, schemars::JsonSchema)]
    pub struct GalleryQueryInput {
        /// Return full specs instead of id/prompt/tags summaries.
        #[serde(default)]
        pub full: bool,
    }
    #[derive(Debug, Clone, Serialize, Deserialize, schemars::JsonSchema)]
    pub struct GalleryListOutput {
        pub count: u32,
        pub specs: Vec<serde_json::Value>,
    }
    #[derive(Debug, Clone, Serialize, Deserialize, schemars::JsonSchema)]
    pub struct SpecIdInput {
        /// Gallery/catalog entry id.
        pub id: String,
    }
    #[derive(Debug, Clone, Serialize, Deserialize, schemars::JsonSchema)]
    pub struct PromoteOutput {
        pub id: String,
        pub catalog_count: u32,
    }

    // Add methods
    use super::plugin_scaffold_helpers::method_decl_from_schemars_with_output;
    use super::plugin_scaffold_helpers::AckOutput;
    use op_state_store::SideEffect;

    schema.methods.insert(
        "classify".to_string(),
        method_decl_from_schemars_with_output::<(), ClassifyOutput>(
            "classify",
            SideEffect::Mutation,
            false,
            "gemma.invoke",
            "mut.service.gemma.classify@v1",
        ),
    );
    schema.methods.insert(
        "route".to_string(),
        method_decl_from_schemars_with_output::<(), RouteOutput>(
            "route",
            SideEffect::Mutation,
            false,
            "gemma.invoke",
            "mut.service.gemma.route@v1",
        ),
    );
    schema.methods.insert(
        "list_perspectives".to_string(),
        method_decl_from_schemars_with_output::<(), ListPerspectivesOutput>(
            "list_perspectives",
            SideEffect::Read,
            true,
            "gemma.read",
            "obs.service.gemma.perspective.list@v1",
        ),
    );
    schema.methods.insert(
        "get_ui_spec".to_string(),
        method_decl_from_schemars_with_output::<(), GetUiSpecOutput>(
            "get_ui_spec",
            SideEffect::Read,
            true,
            "gemma.read",
            "obs.service.gemma.ui-spec.get@v1",
        ),
    );
    schema.methods.insert(
        "list_tags".to_string(),
        method_decl_from_schemars_with_output::<(), ListTagsOutput>(
            "list_tags",
            SideEffect::Read,
            true,
            "gemma.read",
            "obs.service.gemma.tag.list@v1",
        ),
    );
    schema.methods.insert(
        "register_tag".to_string(),
        method_decl_from_schemars_with_output::<(), AckOutput>(
            "register_tag",
            SideEffect::Mutation,
            false,
            "gemma.invoke",
            "mut.service.gemma.tag.register@v1",
        ),
    );
    schema.methods.insert(
        "analyze_intent".to_string(),
        method_decl_from_schemars_with_output::<(), AnalyzeIntentOutput>(
            "analyze_intent",
            SideEffect::Mutation,
            false,
            "gemma.invoke",
            "mut.service.gemma.intent.analyze@v1",
        ),
    );
