// ── MutationEngine dispatch surface ─────────────────────────────────────────
//
// The MutationEngine routes `gemma_brain` MethodCalls here (both the D-Bus
// SchemaBackedInterface path and the gRPC CallMethod path). Inference goes
// through the SAME source the routing brain uses: the `large_language_model`
// plugin's live-resolved provider endpoint + model. No model is hardcoded.

/// Dispatch a `gemma_brain` method call. `json_args` is the verbatim caller
/// argument payload: an object, an args array (gRPC), or a bare string.
pub async fn dispatch_gemma_brain_method(
    method: &str,
    json_args: &str,
) -> anyhow::Result<serde_json::Value> {
    let args = normalize_args(json_args);
    match method {
        "chat" => chat(&args).await,
        "generate_element" => generate_element(&args).await,
        "get_gallery" => list_specs(GEMMA_SPECS_PATH, &args),
        "get_catalog" => list_specs(GEMMA_CATALOG_PATH, &args),
        "promote_spec" => promote_spec(&args),
        "delete_spec" => delete_spec(&args),
        "get_ui_spec" => get_ui_spec(&args),
        "list_perspectives" => Ok(serde_json::json!({
            "perspectives": ["data_numeric", "spatial_layout", "user_flow", "context_aesthetic"]
        })),
        "list_tags" => list_tags(),
        other => anyhow::bail!("gemma_brain: method '{other}' is declared but not yet dispatched"),
    }
}

/// Accept `{...}`, `[{...}, ...]` (gRPC args array), or a bare string.
fn normalize_args(json_args: &str) -> serde_json::Value {
    let parsed: serde_json::Value =
        serde_json::from_str(json_args).unwrap_or(serde_json::Value::Null);
    match parsed {
        serde_json::Value::Array(mut a) if !a.is_empty() => a.remove(0),
        serde_json::Value::Null => serde_json::json!({}),
        other => other,
    }
}

/// Pull a required string field; a bare-string args payload satisfies any field.
fn arg_str(args: &serde_json::Value, field: &str) -> anyhow::Result<String> {
    if let Some(s) = args.as_str() {
        return Ok(s.to_string());
    }
    args.get(field)
        .and_then(serde_json::Value::as_str)
        .map(String::from)
        .ok_or_else(|| anyhow::anyhow!("missing required argument '{field}'"))
}

/// Resolve (endpoint, model, temperature, num_ctx) from the shared
/// large_language_model plugin — the same inference surface routing uses.
async fn resolve_llm() -> anyhow::Result<(String, String, f32, u32)> {
    let llm = super::large_language_model::LargeLanguageModelPlugin::live_state().await;
    anyhow::ensure!(
        llm.status == "online",
        "large_language_model provider offline at {}",
        llm.endpoint
    );
    anyhow::ensure!(
        !llm.model_id.is_empty(),
        "large_language_model resolved no active model"
    );
    Ok((
        llm.endpoint,
        llm.model_id,
        llm.params.temperature,
        llm.params.context_window,
    ))
}

/// One non-streamed chat completion against the resolved provider.
async fn llm_chat(messages: &[serde_json::Value]) -> anyhow::Result<(String, String)> {
    let (endpoint, model, temperature, num_ctx) = resolve_llm().await?;
    let client = reqwest::Client::builder()
        .timeout(std::time::Duration::from_secs(180))
        .build()?;
    let body = serde_json::json!({
        "model": model,
        "messages": messages,
        "stream": false,
        "options": { "temperature": temperature, "num_ctx": num_ctx },
    });
    let resp = client
        .post(format!("{}/api/chat", endpoint.trim_end_matches('/')))
        .json(&body)
        .send()
        .await?
        .error_for_status()?;
    let v: serde_json::Value = resp.json().await?;
    let reply = v
        .pointer("/message/content")
        .and_then(serde_json::Value::as_str)
        .unwrap_or_default()
        .to_string();
    anyhow::ensure!(!reply.is_empty(), "provider returned an empty reply");
    Ok((reply, model))
}

async fn chat(args: &serde_json::Value) -> anyhow::Result<serde_json::Value> {
    let message = arg_str(args, "message")?;
    let reset = args
        .get("reset")
        .and_then(serde_json::Value::as_bool)
        .unwrap_or(false);

    let mut history: Vec<serde_json::Value> = if reset {
        Vec::new()
    } else {
        load_json(GEMMA_CHAT_HISTORY_PATH)
            .get("messages")
            .and_then(serde_json::Value::as_array)
            .cloned()
            .unwrap_or_default()
    };
    history.push(serde_json::json!({ "role": "user", "content": message }));

    let mut messages =
        vec![serde_json::json!({ "role": "system", "content": CHAT_SYSTEM_PROMPT })];
    let start = history.len().saturating_sub(CHAT_CONTEXT_MESSAGES);
    messages.extend_from_slice(&history[start..]);

    let (reply, model) = llm_chat(&messages).await?;
    history.push(serde_json::json!({ "role": "assistant", "content": reply }));
    save_json(
        GEMMA_CHAT_HISTORY_PATH,
        &serde_json::json!({ "version": 1, "messages": history }),
    )?;

    // A build instruction answered with a spec lands in the gallery.
    let spec_id = match extract_json_block(&reply) {
        Some(spec) => Some(append_gallery_entry(
            spec,
            &message,
            vec!["chat".to_string(), "build-instruction".to_string()],
        )?),
        None => None,
    };

    Ok(serde_json::json!({
        "reply": reply,
        "model": model,
        "spec_id": spec_id,
        "gallery_count": GemmaBrainPlugin::spec_count_at(GEMMA_SPECS_PATH),
    }))
}

async fn generate_element(args: &serde_json::Value) -> anyhow::Result<serde_json::Value> {
    let intent = arg_str(args, "intent")?;
    let messages = vec![
        serde_json::json!({ "role": "system", "content": GENERATE_SYSTEM_PROMPT }),
        serde_json::json!({ "role": "user", "content": intent }),
    ];
    let (reply, _model) = llm_chat(&messages).await?;
    let spec = extract_json_block(&reply)
        .ok_or_else(|| anyhow::anyhow!("model reply contained no json spec block"))?;
    let id = append_gallery_entry(
        spec.clone(),
        &intent,
        vec!["chat".to_string(), "generated".to_string()],
    )?;
    Ok(serde_json::json!({
        "id": id,
        "spec": spec,
        "gallery_count": GemmaBrainPlugin::spec_count_at(GEMMA_SPECS_PATH),
    }))
}

fn list_specs(path: &str, args: &serde_json::Value) -> anyhow::Result<serde_json::Value> {
    let full = args
        .get("full")
        .and_then(serde_json::Value::as_bool)
        .unwrap_or(false);
    let doc = load_json(path);
    let specs = doc
        .get("specs")
        .and_then(serde_json::Value::as_array)
        .cloned()
        .unwrap_or_default();
    let out: Vec<serde_json::Value> = if full {
        specs
    } else {
        specs
            .iter()
            .map(|e| {
                serde_json::json!({
                    "id": e.get("id"),
                    "prompt": e.get("prompt"),
                    "tags": e.get("tags"),
                    "created_at": e.get("created_at"),
                    "promoted_at": e.get("promoted_at"),
                })
            })
            .collect()
    };
    Ok(serde_json::json!({ "count": out.len(), "specs": out }))
}

fn get_ui_spec(args: &serde_json::Value) -> anyhow::Result<serde_json::Value> {
    let id = arg_str(args, "id")?;
    for path in [GEMMA_SPECS_PATH, GEMMA_CATALOG_PATH] {
        if let Some(entry) = find_spec(path, &id) {
            return Ok(serde_json::json!({ "spec": entry }));
        }
    }
    Ok(serde_json::json!({ "spec": null }))
}

fn list_tags() -> anyhow::Result<serde_json::Value> {
    let doc = load_json(GEMMA_SPECS_PATH);
    let mut tags: Vec<String> = doc
        .get("specs")
        .and_then(serde_json::Value::as_array)
        .map(|specs| {
            specs
                .iter()
                .flat_map(|e| {
                    e.get("tags")
                        .and_then(serde_json::Value::as_array)
                        .cloned()
                        .unwrap_or_default()
                })
                .filter_map(|t| t.as_str().map(String::from))
                .collect()
        })
        .unwrap_or_default();
    tags.sort();
    tags.dedup();
    Ok(serde_json::json!({ "tags": tags }))
}

/// Promote a gallery entry into the site catalog (copy, idempotent by id).
fn promote_spec(args: &serde_json::Value) -> anyhow::Result<serde_json::Value> {
    let id = arg_str(args, "id")?;
    let entry = find_spec(GEMMA_SPECS_PATH, &id)
        .ok_or_else(|| anyhow::anyhow!("spec '{id}' not found in gallery"))?;

    let mut catalog = load_json(GEMMA_CATALOG_PATH);
    if !catalog.get("specs").map(|s| s.is_array()).unwrap_or(false) {
        catalog = serde_json::json!({ "version": 1, "specs": [] });
    }
    let specs = catalog["specs"].as_array_mut().expect("specs is an array");
    if !specs
        .iter()
        .any(|e| e.get("id").and_then(serde_json::Value::as_str) == Some(id.as_str()))
    {
        let mut promoted = entry;
        promoted["promoted_at"] = serde_json::json!(chrono::Utc::now().timestamp());
        specs.push(promoted);
    }
    let count = specs.len() as u32;
    save_json(GEMMA_CATALOG_PATH, &catalog)?;
    Ok(serde_json::json!({ "id": id, "catalog_count": count }))
}

fn delete_spec(args: &serde_json::Value) -> anyhow::Result<serde_json::Value> {
    let id = arg_str(args, "id")?;
    let mut doc = load_json(GEMMA_SPECS_PATH);
    let mut removed = false;
    if let Some(specs) = doc.get_mut("specs").and_then(serde_json::Value::as_array_mut) {
        let before = specs.len();
        specs.retain(|e| e.get("id").and_then(serde_json::Value::as_str) != Some(id.as_str()));
        removed = specs.len() != before;
        if removed {
            save_json(GEMMA_SPECS_PATH, &doc)?;
        }
    }
    Ok(serde_json::json!({
        "ok": removed,
        "gallery_count": GemmaBrainPlugin::spec_count_at(GEMMA_SPECS_PATH),
    }))
}

/// Append a spec to the gallery; dedupes on structural signature. Returns the
/// entry id (existing id when the same spec is already present).
fn append_gallery_entry(
    spec: serde_json::Value,
    prompt: &str,
    tags: Vec<String>,
) -> anyhow::Result<String> {
    let canonical = serde_json::to_string(&spec)?;
    let signature =
        uuid::Uuid::new_v5(&uuid::Uuid::NAMESPACE_OID, canonical.as_bytes()).to_string();

    let mut doc = load_json(GEMMA_SPECS_PATH);
    if !doc.get("specs").map(|s| s.is_array()).unwrap_or(false) {
        doc = serde_json::json!({ "version": 1, "specs": [] });
    }
    let specs = doc["specs"].as_array_mut().expect("specs is an array");

    if let Some(existing) = specs.iter().find(|e| {
        e.get("signature").and_then(serde_json::Value::as_str) == Some(signature.as_str())
    }) {
        if let Some(id) = existing.get("id").and_then(serde_json::Value::as_str) {
            return Ok(id.to_string());
        }
    }

    let id = format!(
        "chat-{}",
        &uuid::Uuid::new_v4().simple().to_string()[..12]
    );
    specs.push(serde_json::json!({
        "id": id,
        "spec": spec,
        "prompt": prompt,
        "tags": tags,
        "created_at": chrono::Utc::now().timestamp(),
        "signature": signature,
    }));
    save_json(GEMMA_SPECS_PATH, &doc)?;
    Ok(id)
}

fn find_spec(path: &str, id: &str) -> Option<serde_json::Value> {
    load_json(path)
        .get("specs")
        .and_then(serde_json::Value::as_array)
        .and_then(|specs| {
            specs
                .iter()
                .find(|e| e.get("id").and_then(serde_json::Value::as_str) == Some(id))
                .cloned()
        })
}

fn load_json(path: &str) -> serde_json::Value {
    std::fs::read(path)
        .ok()
        .and_then(|bytes| serde_json::from_slice(&bytes).ok())
        .unwrap_or(serde_json::Value::Null)
}

/// Atomic write: tmp file + rename, creating the parent dir if needed.
fn save_json(path: &str, value: &serde_json::Value) -> anyhow::Result<()> {
    let p = std::path::Path::new(path);
    if let Some(parent) = p.parent() {
        std::fs::create_dir_all(parent)?;
    }
    let tmp = p.with_extension("json.tmp");
    std::fs::write(&tmp, serde_json::to_vec_pretty(value)?)?;
    std::fs::rename(&tmp, p)?;
    Ok(())
}

/// Extract the first fenced ```json block (or a bare top-level JSON object)
/// from a model reply.
fn extract_json_block(reply: &str) -> Option<serde_json::Value> {
    let fenced = reply.split("```json").nth(1).and_then(|rest| {
        let body = rest.split("```").next()?;
        serde_json::from_str::<serde_json::Value>(body.trim()).ok()
    });
    let candidate = fenced.or_else(|| {
        let start = reply.find('{')?;
        let end = reply.rfind('}')?;
        serde_json::from_str::<serde_json::Value>(&reply[start..=end]).ok()
    })?;
    candidate.is_object().then_some(candidate)
}

// Self-registration: the plugin registry discovers this via inventory
// (single source of the catalog; no central dispatch list).
inventory::submit! {
    crate::default_registry::PluginReg::new("gemma_brain", |_ctx| std::sync::Arc::new(GemmaBrainPlugin::new()))
}

#[cfg(test)]
mod dispatch_tests {
    use super::*;

    #[test]
    fn normalize_args_accepts_object_array_and_string() {
        assert_eq!(
            normalize_args(r#"{"message":"hi"}"#)["message"],
            serde_json::json!("hi")
        );
        assert_eq!(
            normalize_args(r#"[{"message":"hi"}]"#)["message"],
            serde_json::json!("hi")
        );
        assert_eq!(
            arg_str(&normalize_args(r#""hi""#), "message").unwrap(),
            "hi"
        );
    }

    #[test]
    fn extract_json_block_handles_fenced_and_bare() {
        let fenced = "here you go\n```json\n{\"kind\":\"panel\"}\n```\nreasoning...";
        assert_eq!(
            extract_json_block(fenced).unwrap()["kind"],
            serde_json::json!("panel")
        );
        let bare = "spec: {\"kind\":\"meter\"} end";
        assert_eq!(
            extract_json_block(bare).unwrap()["kind"],
            serde_json::json!("meter")
        );
        assert!(extract_json_block("no spec here").is_none());
    }
}

